import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;


public class HotelBookingFareTest {

    HotelBooking booking;

        @BeforeEach
            void setUp() {
                    booking = new HotelBooking();
                        }

                            @Test
                                @DisplayName("Standard room cost")
                                    void standardRoomCost() {
                                            double cost = booking.calculateBookingCost("Standard", 2);
                                                    assertEquals(8000.0, cost);
                                                        }

                                                            @Test
                                                                @DisplayName("Deluxe room cost")
                                                                    void deluxeRoomCost() {
                                                                            double cost = booking.calculateBookingCost("Deluxe", 5);
                                                                                    assertEquals(30000.0, cost);
                                                                                        }
                                                                                            @Test
                                                                                                void standardBoundary() {
                                                                                                        assertEquals(12000.0, booking.calculateBookingCost("Standard", 3));
                                                                                                            }


                                                                                                                @Test
                                                                                                                    void deluxeBoundary() {
                                                                                                                            assertEquals(14000.0, booking.calculateBookingCost("Deluxe", 2));
                                                                                                                                }

                                                                                                                                    @Test
                                                                                                                                        void standardAboveBoundary() {
                                                                                                                                                assertEquals(14000.0, booking.calculateBookingCost("Standard", 4));
                                                                                                                                                    }

                                                                                                                                                        @Test
                                                                                                                                                            void deluxeAboveBoundary(){
                                                                                                                                                                    assertEquals(18000.0, booking.calculateBookingCost("Deluxe", 3));
                                                                                                                                                                        }

                                                                                                                                                                            @Test
                                                                                                                                                                                void longDurationBooking() {
                                                                                                                                                                                        double cost = booking.calculateBookingCost("Standard", 10);
                                                                                                                                                                                                assertEquals(35000.0, cost);
                                                                                                                                                                                                    }

                                                                                                                                                                                                        @Test
                                                                                                                                                                                                            void invalidRoomType() {
                                                                                                                                                                                                                    assertThrows(IllegalArgumentException.class,
                                                                                                                                                                                                                                () -> booking.calculateBookingCost("Suite", 3));
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                        @Test
                                                                                                                                                                                                                                            void negativeNights() {
                                                                                                                                                                                                                                                    assertThrows(IllegalArgumentException.class,
                                                                                                                                                                                                                                                                () -> booking.calculateBookingCost("Deluxe", -3));
                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                        @Test
                                                                                                                                                                                                                                                                            void zeroNights() {
                                                                                                                                                                                                                                                                                    assertThrows(IllegalArgumentException.class,
                                                                                                                                                                                                                                                                                                () -> booking.calculateBookingCost("Standard", 0));
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                        @Test
                                                                                                                                                                                                                                                                                                            void validBookingCost() {
                                                                                                                                                                                                                                                                                                                    double cost = booking.calculateBookingCost("Deluxe", 4);
                                                                                                                                                                                                                                                                                                                            assertTrue(cost > 0);
                                                                                                                                                                                                                                                                                                                                }



                                                                                                                                                                                                                                                                                                                                    @Test
                                                                                                                                                                                                                                                                                                                                        void failIfNoException() {
                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                            booking.calculateBookingCost("Standard", -2);
                                                                                                                                                                                                                                                                                                                                                                        fail("Exception was not thrown");
                                                                                                                                                                                                                                                                                                                                                                                } catch (IllegalArgumentException e) {
                                                                                                                                                                                                                                                                                                                                                                                            assertEquals("Nights must be greater than zero", e.getMessage());
                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                            @ParameterizedTest
                                                                                                                                                                                                                                                                                                                                                                                                                @CsvSource({
                                                                                                                                                                                                                                                                                                                                                                                                                        "Standard, 1, 4000",
                                                                                                                                                                                                                                                                                                                                                                                                                                "Standard, 3, 12000",
                                                                                                                                                                                                                                                                                                                                                                                                                                        "Standard, 4, 14000",
                                                                                                                                                                                                                                                                                                                                                                                                                                                "Deluxe, 1, 7000",
                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Deluxe, 2, 14000",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Deluxe, 3, 18000",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Deluxe, 10, 60000"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                void costWithCsvSource(String type, int nights, double expected_cost) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        assertEquals(expected_cost, booking.calculateBookingCost(type, nights));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                @ParameterizedTest
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    @ValueSource(ints = {0, -1, -5, -10})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        void invalidNightsWithValueSource(int nights) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assertThrows(IllegalArgumentException.class,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            () -> booking.calculateBookingCost("Standard", nights));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }